const BASE_URL = 'https://uma.moe';

// Full spec: https://uma.moe/api/docs (OpenAPI at /api/docs/openapi.yaml).
// Endpoints are scraping-protected; a valid X-API-Key is required for
// server-to-server access (generated by a uma.moe user from Settings).
async function fetchTrainerProfile(accountId, apiKey) {
  const res = await fetch(`${BASE_URL}/api/v4/user/profile/${accountId}`, {
    headers: {
      'X-API-Key': apiKey,
    },
  });

  if (res.status === 404) {
    return null;
  }

  if (!res.ok) {
    throw new Error(`uma.moe API returned ${res.status} ${res.statusText}`);
  }

  return res.json();
}

// uma.moe's own frontend resolves factor IDs and character names from public,
// unauthenticated, versioned JSON resources (found via their app bundle's
// ResourceData/MasterDataService — GET /resources/manifest.json lists every
// artifact's current path; these two are what "current" always points at, so
// no manifest round-trip is needed). Fetched fresh per lookup rather than
// bundled locally, since these get updated with every game content patch.
const RESOURCES_BASE = `${BASE_URL}/resources/current`;

async function fetchResource(name) {
  const res = await fetch(`${RESOURCES_BASE}/${name}.json.gz`);
  if (!res.ok) {
    throw new Error(`uma.moe ${name} resource returned ${res.status} ${res.statusText}`);
  }
  return res.json();
}

// Array of { id, text, type }. id + a trailing star-level digit is a factor ID
// as seen in inheritance.main_blue_factors etc, e.g. "3201" = base "320" ("Mile",
// type 1) + level 1.
function fetchFactorTable() {
  return fetchResource('factors');
}

// { [4-digit base character id]: { name, skins: { [2-digit variant]: skinName } } }.
// A card/costume ID (e.g. inheritance.main_parent_id) is the base id + 2-digit
// variant, e.g. "101303" = character "1013" (Mejiro McQueen) variant "03".
function fetchCharacterNames() {
  return fetchResource('character_names');
}

// Character portrait, e.g. https://uma.moe/assets/images/character_stand/chara_stand_101303.webp.
// The filename is always `chara_stand_<card id>.webp` (verified against every
// entry in the character resource) — public asset, no auth needed. Returns
// null on any failure rather than throwing, since a missing portrait should
// fall back to the card's placeholder avatar, not break the whole command.
async function fetchCharacterPortrait(cardId) {
  try {
    const res = await fetch(`${BASE_URL}/assets/images/character_stand/chara_stand_${cardId}.webp`);
    if (!res.ok) return null;
    return Buffer.from(await res.arrayBuffer());
  } catch {
    return null;
  }
}

module.exports = { fetchTrainerProfile, fetchFactorTable, fetchCharacterNames, fetchCharacterPortrait };
